def slownik():
    """{zawód: {język: [słowa]}} dla strony."""
    out = {}
    for k, s in S.items():
        out[k] = {}
        for cz in s.split(';'):
            j, _, w = cz.strip().partition(':')
            out[k][j.strip()] = [x.strip() for x in w.split(',') if x.strip()]
    return out
